//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-ranges.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}


#[test]
fn noscript_text_ranges_insert_split_exact_units_records_and_live_boundaries(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var host=document.getElementById('host'),text=host.firstChild,raw='A\udfff\ud800B';text.data=raw;
var r=document.createRange(),alias=document.createRange(),inserted=document.createTextNode('X'),watch=new MutationObserver(function(){});r.setStart(text,2);r.collapse(true);alias.setStart(text,3);alias.setEnd(text,4);watch.observe(host,{childList:true,subtree:true,characterData:true,characterDataOldValue:true});
if(r.insertNode(inserted)!==undefined)throw 'Range insert return';var tail=inserted.nextSibling,rs=watch.takeRecords();
if(host.childNodes.length!==3||host.firstChild!==text||text.data!=='A\udfff'||text.nextSibling!==inserted||tail.data!=='\ud800B'||inserted.parentNode!==host||tail.ownerDocument!==document||r.startContainer!==text||r.startOffset!==2||r.endContainer!==host||r.endOffset!==2||r.collapsed||alias.startContainer!==tail||alias.startOffset!==1||alias.endContainer!==tail||alias.endOffset!==2)throw 'actual passive Range split and insertion';
if(rs.length!==3||rs[0].type!=='childList'||rs[0].target!==host||rs[0].addedNodes[0]!==tail||rs[0].previousSibling!==text||rs[1].type!=='characterData'||rs[1].target!==text||rs[1].oldValue!==raw||rs[2].type!=='childList'||rs[2].target!==host||rs[2].addedNodes[0]!==inserted||rs[2].previousSibling!==text||rs[2].nextSibling!==tail)throw 'ordered Range split insertion records';
var donor=document.createDocumentFragment(),a=document.createTextNode('<b>literal</b>'),b=document.createTextNode('\ud800');donor.append(a,b);watch.observe(donor,{childList:true});r.setStart(host,2);r.collapse(true);r.insertNode(donor);rs=watch.takeRecords();if(donor.firstChild!==null||host.childNodes[2]!==a||host.childNodes[3]!==b||b.nextSibling!==tail||r.startContainer!==host||r.startOffset!==2||r.endContainer!==host||r.endOffset!==4||rs.length!==2||rs[0].target!==donor||rs[0].removedNodes[0]!==a||rs[0].removedNodes[1]!==b||rs[1].target!==host||rs[1].addedNodes[0]!==a||rs[1].addedNodes[1]!==b||document.querySelectorAll('b').length)throw 'actual Text-only Range fragment drain';
"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_ranges_clone_and_extract_partial_units_preserve_native_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var host=document.getElementById('host'),a=document.createTextNode('A\udfff'),middle=document.createTextNode('<i>literal</i>'),z=document.createTextNode('\ud800Z');host.replaceChildren(a,middle,z);var r=document.createRange(),watch=new MutationObserver(function(){});r.setStart(a,1);r.setEnd(z,1);watch.observe(host,{childList:true,subtree:true,characterData:true,characterDataOldValue:true});
var clone=r.cloneContents();if(clone.nodeType!==11||clone.ownerDocument!==document||clone.childNodes.length!==3||clone.firstChild===a||clone.childNodes[1]===middle||clone.lastChild===z||clone.firstChild.data!=='\udfff'||clone.childNodes[1].data!=='<i>literal</i>'||clone.lastChild.data!=='\ud800'||host.firstChild!==a||middle.parentNode!==host||z.data!=='\ud800Z'||watch.takeRecords().length||r.startContainer!==a||r.startOffset!==1||r.endContainer!==z||r.endOffset!==1)throw 'passive clone exact detached copies no source effects';
var extracted=r.extractContents(),rs=watch.takeRecords();if(extracted.ownerDocument!==document||extracted.childNodes.length!==3||extracted.firstChild===a||extracted.childNodes[1]!==middle||middle.parentNode!==extracted||extracted.lastChild===z||extracted.firstChild.data!=='\udfff'||extracted.lastChild.data!=='\ud800'||a.data!=='A'||z.data!=='Z'||host.childNodes.length!==2||a.nextSibling!==z||r.startContainer!==host||r.startOffset!==1||!r.collapsed)throw 'passive extraction partial clones and whole Text identity';
if(rs.length!==3||rs[0].type!=='characterData'||rs[0].target!==a||rs[0].oldValue!=='A\udfff'||rs[1].type!=='childList'||rs[1].target!==host||rs[1].removedNodes[0]!==middle||rs[1].previousSibling!==a||rs[1].nextSibling!==z||rs[2].type!=='characterData'||rs[2].target!==z||rs[2].oldValue!=='\ud800Z')throw 'ordered actual extraction records';host.appendChild(extracted);rs=watch.takeRecords();if(extracted.firstChild!==null||host.childNodes[3]!==middle||rs.length!==1||rs[0].addedNodes.length!==3||document.querySelectorAll('i').length)throw 'extracted Text fragment reinsertion stays literal';
"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_ranges_delete_partial_units_and_full_text_saved_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var host=document.getElementById('host'),a=document.createTextNode('A\udfff'),middle=document.createTextNode('<b>literal</b>'),z=document.createTextNode('\ud800Z');host.replaceChildren(a,middle,z);var r=document.createRange(),inside=document.createRange(),fixed=new StaticRange({startContainer:middle,startOffset:1,endContainer:middle,endOffset:2}),watch=new MutationObserver(function(){});r.setStart(a,1);r.setEnd(z,1);inside.selectNodeContents(middle);watch.observe(host,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});if(r.deleteContents()!==undefined)throw 'Range delete return';var rs=watch.takeRecords();if(a.data!=='A'||z.data!=='Z'||host.childNodes.length!==2||a.nextSibling!==z||middle.parentNode!==null||middle.data!=='<b>literal</b>'||middle.ownerDocument!==document||r.startContainer!==host||r.startOffset!==1||!r.collapsed||inside.startContainer!==host||inside.startOffset!==1||!inside.collapsed||fixed.startContainer!==middle||fixed.startOffset!==1||fixed.endContainer!==middle||fixed.endOffset!==2||rs.length!==3||rs[0].target!==a||rs[0].oldValue!=='A\udfff'||rs[1].target!==host||rs[1].removedNodes[0]!==middle||rs[2].target!==z||rs[2].oldValue!=='\ud800Z')throw 'actual passive Range deletion and boundary relocation';
r.deleteContents();if(watch.takeRecords().length||host.textContent!=='AZ')throw 'collapsed deletion no mutation';r.selectNodeContents(host);r.deleteContents();rs=watch.takeRecords();if(host.firstChild!==null||a.parentNode!==null||z.parentNode!==null||a.data!=='A'||z.data!=='Z'||rs.length!==2||rs[0].removedNodes[0]!==a||rs[1].removedNodes[0]!==z||!r.collapsed||r.startContainer!==host||r.startOffset)throw 'whole passive Text deletion';host.appendChild(middle);if(host.firstChild!==middle||middle.data!=='<b>literal</b>'||document.querySelectorAll('b').length)throw 'saved Text recovery literal';
"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_ranges_native_insert_guards_and_clone_quota_refusal_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),text=host.firstChild,guarded=document.getElementById('guard'),blocked=guarded.firstChild,span=document.createElement('span'),r=document.createRange(),g=document.createRange(),watch=new MutationObserver(function(){});r.selectNodeContents(host);r.collapse(true);g.setStart(blocked,2);g.collapse(true);var s=document.createRange(),mixed=document.createDocumentFragment();s.setStart(text,2);s.collapse(true);mixed.appendChild(document.createTextNode('literal'));mixed.appendChild(document.createElement('em'));watch.observe(document.body,{subtree:true,childList:true,characterData:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for code in ["r.insertNode(span);","r.insertNode(blocked);","g.insertNode(text);","s.insertNode(span);","s.insertNode(blocked);","s.insertNode(mixed);"]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains("inert resource subtrees"),"{code}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||guarded.firstChild!==blocked||span.parentNode!==null||watch.takeRecords().length||r.startContainer!==host||r.startOffset||!r.collapsed||s.startContainer!==text||s.startOffset!==2||!s.collapsed||g.startContainer!==blocked||g.startOffset!==2||!g.collapsed||mixed.childNodes.length!==2)throw 'Range initial native guard atomic';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"r.selectNodeContents(text);");let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=refusal(&mut d,&mut f,&mut p,"r.cloneContents();").to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(text.data!=='held'||text.parentNode!==host||r.startContainer!==text||r.startOffset||r.endContainer!==text||r.endOffset!==4||watch.takeRecords().length)throw 'Range clone initial quota preserves source';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"var copied=r.cloneContents();if(copied.firstChild===text||copied.firstChild.data!=='held'||copied.ownerDocument!==document||text.parentNode!==host||watch.takeRecords().length)throw 'fresh clone recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
